                <button onClick="{{ planAddGo }}" aria-label="Agregar" style="width:46px;height:46px;flex:none;border:1px solid color-mix(in oklab, #fff 62%, transparent);border-radius:50%;background:linear-gradient(150deg, color-mix(in oklab, #fff 62%, transparent) 0%, transparent 48%), color-mix(in oklab, var(--acento) 74%, transparent);-webkit-backdrop-filter:blur(20px) saturate(1.9);backdrop-filter:blur(20px) saturate(1.9);box-shadow:0 8px 22px oklch(0.82 0.16 95 / 0.5), inset 0 1px 1px color-mix(in oklab, #fff 85%, transparent);color:var(--sobre-acento);cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 6px 16px oklch(0.62 0.14 95 / 0.4)"><svg viewBox="0 0 24 24" style="width:23px;height:23px" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M12 5v14M5 12h14"></path></svg></button>
